echo "== parent of pid 13 ==" ; ps -o pid,ppid,user,args -p "$(ps -o ppid= -p 13 | tr -d ' ')" 2>&1
echo "== ip addresses ==" ; (ip -br addr 2>/dev/null || cat /proc/net/fib_trie | grep -E '^\s+\|--' | head -n 20)
echo "== references to 8080 in typical startup locations ==" ; grep -rIl "8080" /etc /root /opt /srv /usr/local/bin 2>/dev/null | head -n 20 || true

echo "== ufw ==";
if command -v ufw >/dev/null 2>&1; then ufw status verbose; else echo "ufw не установлен"; fi
echo;
echo "== iptables (INPUT) ==";
if command -v iptables >/dev/null 2>&1; then iptables -S INPUT; iptables -S INPUT | head -0; iptables -L INPUT -n -v --line-numbers; else echo "iptables не найден"; fi
echo;
echo "== Порт 8080 ==";
ss -tlnp | grep -E ':8080\b' || echo "Ничего не слушает на 8080"

echo "== Процесс pid 13 ==";
ps -o pid,ppid,user,args -p 13 2>/dev/null || echo "процесс 13 не найден"
echo;
echo "== Рабочая директория и файлы ==";
ls -l /proc/13/cwd 2>/dev/null
echo;
echo "== Поиск 127.0.0.1 / 0.0.0.0 в типичных местах конфигурации ==";
grep -rIn --exclude-dir=proc --exclude-dir=sys -E "8080|127\.0\.0\.1|0\.0\.0\.0" /etc /opt /srv /home /root 2>/dev/null | grep -v '^Binary' | head -50

transcript.content:
Сначала посмотрю, какой фаервол используется и что сейчас открыто, и слушает ли что-то на порту 8080.

```bash
echo "== ufw ==";
if command -v ufw >/dev/null 2>&1; then ufw status verbose; else echo "ufw не установлен"; fi
echo;
echo "== iptables (INPUT) ==";
if command -v iptables >/dev/null 2>&1; then iptables -S INPUT; iptables -S INPUT | head -0; iptables -L INPUT -n -v --line-numbers; else echo "iptables не найден"; fi
echo;
echo "== Порт 8080 ==";
ss -tlnp | grep -E ':8080\b' || echo "Ничего не слушает на 8080"
```

Фаервола на сервере нет: ни ufw, ни iptables не установлены. Но сервис слушает только `127.0.0.1:8080`, то есть принимает подключения только с самого сервера. Поэтому клиенты не могут подключиться, даже если открыть порт. Посмотрю, как запущен процесс и где задан адрес прослушивания.

```bash
echo "== Процесс pid 13 ==";
ps -o pid,ppid,user,args -p 13 2>/dev/null || echo "процесс 13 не найден"
echo;
echo "== Рабочая директория и файлы ==";
ls -l /proc/13/cwd 2>/dev/null
echo;
echo "== Поиск 127.0.0.1 / 0.0.0.0 в типичных местах конфигурации ==";
grep -rIn --exclude-dir=proc --exclude-dir=sys -E "8080|127\.0\.0\.1|0\.0\.0\.0" /etc /opt /srv /home /root 2>/dev/null | grep -v '^Binary' | head -50
```

